WITH RecentTransactions AS (SELECT *, TO_DATE(txn_time) AS txn_time_date FROM transactions WHERE is_flagged OR is_flagged = TRUE), summary AS (SELECT CASE WHEN amount >= 3800 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END AS amount_bucket, YEAR(txn_time_date) AS txn_year, ROUND(AVG(amount), 2) AS avg_amount FROM RecentTransactions GROUP BY CASE WHEN amount >= 3800 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END, YEAR(txn_time_date)) SELECT amount_bucket, txn_year, avg_amount FROM summary WHERE avg_amount >= 49
